#include <string>
#include <sstream>

std::string convertToHtml(const std::string& text) {
    std::string htmlText;
    std::stringstream ss;

    // Replace all non-ASCII characters with their HTML entities
    for (char c : text) {
        if (!std::isascii(c)) {
            std::string entity = "&#" + std::to_string(c) + ";";
            ss << entity;
        } else {
            ss << c;
        }
    }

    // Convert line breaks to HTML breaks and paragraphs
    std::string lineBreaks = "\n\n";
    std::string htmlBreaks = "<br /><br />";
    std::string htmlParagraphs = "<p>";

    size_t lastLineBreakIndex = 0;
    while ((lastLineBreakIndex = text.find(lineBreaks, lastLineBreakIndex + 1)) != std::string::npos) {
        size_t paragraphEndIndex = lastLineBreakIndex - 1;
        while (paragraphEndIndex > 0 && !std::isspace(text[paragraphEndIndex])) {
            --paragraphEndIndex;
        }
        if (paragraphEndIndex != std::string::npos) {
            ss << htmlParagraphs << text.substr(paragraphEndIndex + 1, lastLineBreakIndex - paragraphEndIndex - 1) << "</p>";
            lastLineBreakIndex += 2; // Skip the second newline
        } else {
            ss << htmlBreaks;
            lastLineBreakIndex += lineBreaks.length();
        }
    }

    if (!htmlText.empty()) {
        htmlText += ss.str();
    } else {
        htmlText = ss.str();
    }

    return htmlText;
}
```

