\usepackage{chessboard} % load the chessboard package

% define a command to parse the FEN notation and return a board object
\newcommand{\parseFEN}[1]{
  \chessboardsetup{showmover=false, showlegalmoves=false, 
                   boardsize=8, boardcolor=white}
  \chessboard{#1} % pass the FEN notation to the chessboard environment
}

