    }
    return count;
}

int main() {
    string fileName;
    string word;

    cout << "Enter file name: ";
    cin >> fileName;

    cout << "Enter word to search: ";
    cin >> word;

    // Open file
    ifstream file(fileName);
    if (!file.is_open()) {
        cerr << "Error opening file." << endl;
        return 1;
    }

    // Read file into vector of lines
    vector<string> lines;
    string line;
    while (getline(file, line)) {
        lines.push_back(line);
    }

    // Close file
    file.close();

    // Count occurrences of word in file
    int count = countWordOccurrences(word, lines);

    // Output result
    cout << "Number of occurrences of \"" << word << "\" in file \"" << fileName << "\": " << count << endl;

    return 0;
}
